phase1.code:
fn main() {
    // ---- Ownership Rules ----
    // 1. Each value has a single owner
    // 2. When the owner goes out of scope, the value is dropped
    // 3. Ownership can be moved

    // ---- String literal (stored in binary, immutable) ----
    let s1 = "hello";  // s1 is a string literal
    println!("s1: {}", s1);

    // ---- String (heap-allocated, owned) ----
    let s2 = String::from("hello");  // s2 owns the String
    println!("s2: {}", s2);

    // ---- Move (ownership transferred) ----
    let s3 = s2;  // s2 is MOVED to s3
    // println!("{}", s2);  // ERROR! s2 no longer owns the String
    println!("s3: {}", s3);

    // ---- Clone (deep copy) ----
    let s4 = s3.clone();  // s3 is CLONED, both own separate data
    println!("s3: {}", s3);
    println!("s4: {}", s4);

    // ---- Copy types (simple, stack-only) ----
    let x = 5;
    let y = x;  // x is COPIED (not moved)
    println!("x: {}, y: {}", x, y);

    // ---- Ownership and functions ----
    let s5 = String::from("world");
    take_ownership(s5);  // s5 is MOVED into the function
    // println!("{}", s5);  // ERROR! s5 no longer owns the String

    let x2 = 10;
    make_copy(x2);  // x2 is COPIED into the function
    println!("x2 is still valid: {}", x2);

    // ---- Returning ownership ----
    let s6 = give_ownership();  // function returns ownership
    println!("s6: {}", s6);
}

fn take_ownership(s: String) {
    println!("take_ownership: {}", s);
}  // s is dropped here

fn make_copy(x: i32) {
    println!("make_copy: {}", x);
}

fn give_ownership() -> String {
    let s = String::from("returned");
    s  // ownership moves to caller
}

// ---- Out of scope ----
// s3 is dropped at the end of main
// s4 is dropped at the end of main
// s6 is dropped at the end of main

